-- =====================================================================
--  Smart HR System - Database Schema (3.1.0)
--  MySQL 8.x / MariaDB 10.4+   |   Charset utf8mb4
--  Contains: structure + essential seed (roles, users, settings, the
--  Province of Punjab — 41 districts, their tehsils and departments —
--  and the other masters). Demo employees & service records are in
--  demo_data.sql. Existing 2.x installs upgrade with
--  the files in migrations/ instead.
-- =====================================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET time_zone = '+05:00';

-- ---------------------------------------------------------------------
-- AUTH & CONFIG
-- ---------------------------------------------------------------------
-- Roles: super_admin, officer, report_viewer, employee. An officer belongs to
-- one department and reaches what that department's level reaches.

DROP TABLE IF EXISTS `roles`;
CREATE TABLE `roles` (
  `id` tinyint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(40) NOT NULL,
  `label` varchar(80) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_roles_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `username` varchar(60) NOT NULL,
  `password` varchar(255) NOT NULL,
  `full_name` varchar(120) NOT NULL,
  `email` varchar(120) DEFAULT NULL,
  `phone` varchar(30) DEFAULT NULL,
  `role_id` tinyint unsigned NOT NULL,
  `employee_id` int unsigned DEFAULT NULL,
  `department_id` int unsigned DEFAULT NULL,
  `must_change_password` tinyint(1) NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `deleted_at` datetime DEFAULT NULL,
  `last_login_at` datetime DEFAULT NULL,
  `last_login_ip` varchar(45) DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_users_username` (`username`),
  KEY `idx_users_role` (`role_id`),
  KEY `idx_users_employee` (`employee_id`),
  KEY `idx_users_department` (`department_id`),
  CONSTRAINT `fk_user_department` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`),
  CONSTRAINT `fk_user_employee` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`),
  CONSTRAINT `fk_users_role` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `settings`;
CREATE TABLE `settings` (
  `setting_key` varchar(80) NOT NULL,
  `setting_value` text,
  `description` varchar(255) DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`setting_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `audit_logs`;
CREATE TABLE `audit_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned DEFAULT NULL,
  `username` varchar(60) DEFAULT NULL,
  `action` varchar(40) NOT NULL,
  `table_name` varchar(60) DEFAULT NULL,
  `record_id` int unsigned DEFAULT NULL,
  `employee_id` int unsigned DEFAULT NULL,
  `description` varchar(255) DEFAULT NULL,
  `old_values` json DEFAULT NULL,
  `new_values` json DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_audit_user` (`user_id`),
  KEY `idx_audit_table` (`table_name`,`record_id`),
  KEY `idx_audit_employee` (`employee_id`),
  KEY `idx_audit_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------
-- GEOGRAPHY — District -> Tehsil -> Department
-- ---------------------------------------------------------------------
-- Level 1  districts     (grouped by division)
-- Level 2  tehsils       each belongs to one district
-- Level 3  departments   each sits in one district and, unless it is at district
--                        headquarters, in one tehsil OF THAT district. The
--                        composite key (tehsil_id, district_id) -> tehsils(id, district_id)
--                        makes a tehsil from another district impossible.
-- departments.level is the authority the office carries:
--   district    the whole district (Deputy Commissioner Office) — no tehsil
--   tehsil      its tehsil (Assistant Commissioner Office)      — tehsil required
--   department  only itself (a single authority)

DROP TABLE IF EXISTS `districts`;
CREATE TABLE `districts` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `division` varchar(80) DEFAULT NULL,
  `name` varchar(120) NOT NULL,
  `code` varchar(20) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_district_name` (`name`),
  UNIQUE KEY `uq_district_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `tehsils`;
CREATE TABLE `tehsils` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `district_id` int unsigned NOT NULL,
  `name` varchar(120) NOT NULL,
  `code` varchar(20) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_tehsil_name` (`district_id`,`name`),
  UNIQUE KEY `uq_tehsil_code` (`district_id`,`code`),
  UNIQUE KEY `uq_tehsil_in_district` (`id`,`district_id`),
  CONSTRAINT `fk_tehsil_district` FOREIGN KEY (`district_id`) REFERENCES `districts` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `departments`;
CREATE TABLE `departments` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(160) NOT NULL,
  `code` varchar(20) NOT NULL,
  `level` enum('district','tehsil','department') NOT NULL DEFAULT 'department',
  `district_id` int unsigned NOT NULL,
  `tehsil_id` int unsigned DEFAULT NULL,
  `head_designation` varchar(120) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `description` varchar(255) DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_department_name` (`name`),
  UNIQUE KEY `uq_department_code` (`code`),
  KEY `idx_department_district` (`district_id`,`level`),
  KEY `idx_department_tehsil` (`tehsil_id`,`level`),
  KEY `fk_department_tehsil` (`tehsil_id`,`district_id`),
  CONSTRAINT `fk_department_district` FOREIGN KEY (`district_id`) REFERENCES `districts` (`id`),
  CONSTRAINT `fk_department_tehsil` FOREIGN KEY (`tehsil_id`, `district_id`) REFERENCES `tehsils` (`id`, `district_id`),
  CONSTRAINT `chk_department_level` CHECK ((((`level` = 'district') and (`tehsil_id` is null)) or ((`level` = 'tehsil') and (`tehsil_id` is not null)) or (`level` = 'department')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `signing_profiles`;
CREATE TABLE `signing_profiles` (
  `user_id` int unsigned NOT NULL,
  `letterhead_1` varchar(120) DEFAULT NULL,
  `letterhead_2` varchar(120) DEFAULT NULL,
  `letterhead_3` varchar(120) DEFAULT NULL,
  `show_emblem` tinyint(1) NOT NULL DEFAULT '1',
  `order_prefix` varchar(40) DEFAULT NULL,
  `authority_name` varchar(120) DEFAULT NULL,
  `authority_designation` varchar(120) DEFAULT NULL,
  `authority_office` varchar(160) DEFAULT NULL,
  `copy_to` text,
  `footer_note` varchar(300) DEFAULT NULL,
  `signature_file` varchar(120) DEFAULT NULL,
  `signature_width` smallint unsigned NOT NULL DEFAULT '150',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------
-- MASTER DATA  (all share: is_active, is_deleted, sort_order)
-- ---------------------------------------------------------------------
-- Offices & sites (posting_locations) belong to a department; their district and
-- tehsil are the department's and are not stored twice.

DROP TABLE IF EXISTS `pay_scales`;
CREATE TABLE `pay_scales` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(30) NOT NULL,
  `scale_number` tinyint unsigned DEFAULT NULL,
  `min_salary` decimal(12,2) DEFAULT NULL,
  `increment_amount` decimal(10,2) DEFAULT NULL,
  `max_salary` decimal(12,2) DEFAULT NULL,
  `description` varchar(255) DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_scale_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `designations`;
CREATE TABLE `designations` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(120) NOT NULL,
  `pay_scale_id` int unsigned DEFAULT NULL,
  `description` varchar(255) DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_desig_scale` (`pay_scale_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `leave_types`;
CREATE TABLE `leave_types` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(80) NOT NULL,
  `is_paid` tinyint(1) NOT NULL DEFAULT '1',
  `is_eol` tinyint(1) NOT NULL DEFAULT '0',
  `is_lpr` tinyint(1) NOT NULL DEFAULT '0',
  `max_days` int DEFAULT NULL,
  `description` varchar(255) DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `award_types`;
CREATE TABLE `award_types` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(80) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `punishment_types`;
CREATE TABLE `punishment_types` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(80) NOT NULL,
  `is_suspension` tinyint(1) NOT NULL DEFAULT '0',
  `is_removal` tinyint(1) NOT NULL DEFAULT '0',
  `is_dismissal` tinyint(1) NOT NULL DEFAULT '0',
  `severity` enum('Minor','Major') NOT NULL DEFAULT 'Minor',
  `description` varchar(255) DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `inquiry_types`;
CREATE TABLE `inquiry_types` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(120) NOT NULL,
  `is_formal` tinyint(1) NOT NULL DEFAULT '0',
  `description` varchar(255) DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `posting_locations`;
CREATE TABLE `posting_locations` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(120) NOT NULL,
  `department_id` int unsigned NOT NULL,
  `address` varchar(255) DEFAULT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `description` varchar(255) DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_loc_dept` (`department_id`),
  CONSTRAINT `fk_location_department` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `employment_types`;
CREATE TABLE `employment_types` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(80) NOT NULL,
  `is_contract` tinyint(1) NOT NULL DEFAULT '0',
  `has_probation` tinyint(1) NOT NULL DEFAULT '1',
  `description` varchar(255) DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `blood_groups`;
CREATE TABLE `blood_groups` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(10) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `marital_statuses`;
CREATE TABLE `marital_statuses` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(40) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `deputation_orgs`;
CREATE TABLE `deputation_orgs` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(150) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `reinstatement_types`;
CREATE TABLE `reinstatement_types` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `with_back_benefits` tinyint(1) NOT NULL DEFAULT '0',
  `description` varchar(255) DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `sanctioned_posts`;
CREATE TABLE `sanctioned_posts` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `department_id` int unsigned NOT NULL,
  `designation_id` int unsigned NOT NULL,
  `pay_scale_id` int unsigned DEFAULT NULL,
  `sanctioned_count` int unsigned NOT NULL DEFAULT '0',
  `remarks` varchar(255) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sanction` (`department_id`,`designation_id`),
  KEY `idx_sanction_desig` (`designation_id`),
  CONSTRAINT `fk_sanction_department` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------
-- EMPLOYEES
-- ---------------------------------------------------------------------
-- An employee belongs to a department; tehsil and district follow from it.

DROP TABLE IF EXISTS `employees`;
CREATE TABLE `employees` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `employee_code` varchar(40) NOT NULL,
  `cnic` varchar(15) NOT NULL,
  `name` varchar(120) NOT NULL,
  `father_husband_name` varchar(120) NOT NULL,
  `gender` enum('Male','Female','Other') NOT NULL DEFAULT 'Male',
  `dob` date NOT NULL,
  `marital_status_id` int unsigned DEFAULT NULL,
  `blood_group_id` int unsigned DEFAULT NULL,
  `contact` varchar(30) DEFAULT NULL,
  `whatsapp_no` varchar(30) DEFAULT NULL,
  `email` varchar(120) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `photo` varchar(255) DEFAULT NULL,
  `department_id` int unsigned NOT NULL,
  `designation_id` int unsigned NOT NULL,
  `pay_scale_id` int unsigned DEFAULT NULL,
  `basic_salary` decimal(12,2) DEFAULT NULL,
  `joining_date` date NOT NULL,
  `employment_type_id` int unsigned DEFAULT NULL,
  `contract_from` date DEFAULT NULL,
  `contract_to` date DEFAULT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'Probation',
  `probation_start` date DEFAULT NULL,
  `probation_end` date DEFAULT NULL,
  `confirmation_date` date DEFAULT NULL,
  `confirmation_order_no` varchar(80) DEFAULT NULL,
  `service_book_no` varchar(50) DEFAULT NULL,
  `gp_fund_no` varchar(50) DEFAULT NULL,
  `pension_no` varchar(50) DEFAULT NULL,
  `seniority_no` varchar(50) DEFAULT NULL,
  `retirement_date` date DEFAULT NULL,
  `eol_break_days` int NOT NULL DEFAULT '0',
  `has_break_in_service` tinyint(1) NOT NULL DEFAULT '0',
  `is_lpr_eligible` tinyint(1) NOT NULL DEFAULT '0',
  `service_closed` tinyint(1) NOT NULL DEFAULT '0',
  `current_posting_id` int unsigned DEFAULT NULL,
  `remarks` text,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int unsigned DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_emp_code` (`employee_code`),
  UNIQUE KEY `uq_emp_cnic` (`cnic`),
  KEY `idx_emp_name` (`name`),
  KEY `idx_emp_dept` (`department_id`),
  KEY `idx_emp_desig` (`designation_id`),
  KEY `idx_emp_status` (`status`),
  KEY `idx_emp_dob` (`dob`),
  KEY `idx_emp_contract_to` (`contract_to`),
  KEY `idx_emp_retirement` (`retirement_date`),
  KEY `idx_emp_probation` (`probation_end`),
  KEY `idx_emp_active` (`is_active`,`is_deleted`),
  CONSTRAINT `fk_employee_department` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `employee_family`;
CREATE TABLE `employee_family` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` int unsigned NOT NULL,
  `relation` varchar(40) NOT NULL,
  `name` varchar(120) NOT NULL,
  `cnic` varchar(15) DEFAULT NULL,
  `dob` date DEFAULT NULL,
  `contact` varchar(30) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `is_nominee` tinyint(1) NOT NULL DEFAULT '0',
  `nominee_share` decimal(5,2) DEFAULT NULL,
  `is_emergency_contact` tinyint(1) NOT NULL DEFAULT '0',
  `is_pension_claimant` tinyint(1) NOT NULL DEFAULT '0',
  `remarks` varchar(255) DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_family_emp` (`employee_id`),
  CONSTRAINT `fk_family_employee` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `employee_documents`;
CREATE TABLE `employee_documents` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` int unsigned NOT NULL,
  `doc_type` varchar(60) NOT NULL,
  `title` varchar(150) NOT NULL,
  `file_path` varchar(255) NOT NULL,
  `original_name` varchar(255) DEFAULT NULL,
  `mime_type` varchar(100) DEFAULT NULL,
  `file_size` int unsigned DEFAULT NULL,
  `related_table` varchar(60) DEFAULT NULL,
  `related_id` int unsigned DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `uploaded_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_doc_emp` (`employee_id`),
  KEY `idx_doc_related` (`related_table`,`related_id`),
  CONSTRAINT `fk_document_employee` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------
-- SERVICE RECORDS  (append-only; never edited; super admin may VOID)
-- ---------------------------------------------------------------------

DROP TABLE IF EXISTS `postings`;
CREATE TABLE `postings` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `ref_no` varchar(30) DEFAULT NULL,
  `employee_id` int unsigned NOT NULL,
  `office` varchar(150) DEFAULT NULL,
  `department_id` int unsigned NOT NULL,
  `section` varchar(120) DEFAULT NULL,
  `location_id` int unsigned DEFAULT NULL,
  `posting_type` varchar(40) NOT NULL,
  `effective_date` date NOT NULL,
  `end_date` date DEFAULT NULL,
  `order_no` varchar(80) DEFAULT NULL,
  `order_date` date DEFAULT NULL,
  `reporting_officer` varchar(120) DEFAULT NULL,
  `deputation_org_id` int unsigned DEFAULT NULL,
  `expected_reversion_date` date DEFAULT NULL,
  `remarks` varchar(500) DEFAULT NULL,
  `is_current` tinyint(1) NOT NULL DEFAULT '1',
  `is_voided` tinyint(1) NOT NULL DEFAULT '0',
  `void_reason` varchar(255) DEFAULT NULL,
  `voided_by` int unsigned DEFAULT NULL,
  `voided_at` datetime DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
